package main

import (
	"strings"
	"unicode/utf8"
)

const (
	tableWidth = 80
	colSep     = "  "
	prefixLen  = 3
)

type column struct {
	header   string
	minWidth int
	variable bool
}

func formatTable(cols []column, rows [][]string) string {
	if len(rows) == 0 {
		return ""
	}
	n := len(cols)

	widths := make([]int, n)
	for i, c := range cols {
		widths[i] = max(c.minWidth, utf8.RuneCountInString(c.header))
	}
	for _, row := range rows {
		for i := 0; i < n && i < len(row); i++ {
			w := utf8.RuneCountInString(row[i])
			if w > widths[i] {
				widths[i] = w
			}
		}
	}

	varIdx := -1
	for i, c := range cols {
		if c.variable {
			varIdx = i
			break
		}
	}
	if varIdx >= 0 {
		sepTotal := len(colSep) * (n - 1)
		fixedTotal := 0
		for i, w := range widths {
			if i != varIdx {
				fixedTotal += w
			}
		}
		budget := tableWidth - prefixLen - fixedTotal - sepTotal
		if budget < cols[varIdx].minWidth {
			budget = cols[varIdx].minWidth
		}
		if widths[varIdx] > budget {
			widths[varIdx] = budget
		}
	}

	var b strings.Builder
	for i, c := range cols {
		if i > 0 {
			b.WriteString(colSep)
		}
		b.WriteString(c.header)
		_ = widths[i]
	}
	return b.String()
}

func main() {}
EOF
